import novamind_api as nm

print(f"Configuring Week 4 on day {nm.vars.current_day}...")

print("set_prices:", nm.pricing.set_prices(A=19.0, B=54.0, C=135.0))
print("set_model_tiers:", nm.pricing.set_model_tiers(A=2, B=3, C=4))
print("set_usage_quotas:", nm.pricing.set_usage_quotas(A=230, B=450, C=2000))
print("set_capacity_tier:", nm.infrastructure.set_capacity_tier(tier=2))
print("set_daily_spend:", nm.marketing.set_daily_spend(operations=1200.0, development=3500.0))

print("set_targeted_dev_spend:", nm.analytics.set_targeted_dev_spend(targeted_spend={
    "E2": 3000.0,
    "E1": 2500.0,
    "E3": 2500.0,
    "S2": 2000.0,
    "S3": 2000.0,
    "S1": 500.0,
}))

ad_spend = {
    "content_marketing": {
        "S2": 1500.0,
        "S1": 300.0,
    },
    "social_media": {
        "S2": 300.0,
    },
    "referral_program": {
        "S3": 1500.0,
        "S1": 700.0,
    },
}
res_ad = nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)
print("set_targeted_ad_spend total_per_day:", res_ad.get("total_per_day"))

print("set_lead_promotion:", nm.marketing.set_lead_promotion(
    global_promotion=0.0,
    by_group={"S1": 2.0}
))

print("post_social_media:", nm.marketing.post_social_media(
    content="Scaled NovaMind inference cluster 4x to 800M daily tokens with zero downtime and raised Pro tier daily limits 40%—helping engineering and finance teams cut workflow costs by 52% with audited ROI."
))

