arguments.content:
import json
import novamind_api as nm

print(f"Configuring Week 7 on day {nm.vars.current_day}...")

# 1. Query all open enterprise threads awaiting agent response
ent = nm.query("""
    SELECT t.message_id, t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.day, t.seat_count, t.offer_json, t.message_text
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    WHERE t.thread_id IN (
        SELECT thread_id FROM enterprise_turns GROUP BY thread_id HAVING MAX(COALESCE(closed, 0)) = 0
    )
    AND t.message_id IN (
        SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id
    )
    ORDER BY t.day, t.thread_id
""")

awaiting = [r for r in ent["rows"] if r["sender"] != "agent"]
print(f"Found {len(ent['rows'])} open threads, {len(awaiting)} awaiting agent reply.")

deals = []
for r in awaiting:
    cid = r["customer_id"]
    gid = r["group_id"]
    turn = r["turn_number"]
    if turn == 0:
        if gid == "E1":
            offerings = [["A", 11.5], ["B", 16.5]]
        elif gid == "E2":
            offerings = [["C", 82.0], ["B", 49.0]]
        elif gid == "E3":
            offerings = [["C", 68.0], ["B", 44.0], ["A", 24.0]]
        elif gid == "D_E02":
            offerings = [["C", 54.0], ["B", 34.0], ["A", 19.0]]
        elif gid == "D_E09":
            offerings = [["C", 46.0], ["B", 29.0], ["A", 17.0]]
        else:
            offerings = [["C", 65.0], ["B", 42.0], ["A", 22.0]]
    else:
        try:
            c_price = float(json.loads(r["offer_json"] or "{}").get("price", 10.0))
        except Exception:
            c_price = 10.0
        if gid == "E1":
            p_a = max(7.5, round(min(10.5, c_price * 0.9), 2))
            p_b = max(15.0, round(c_price + 2.5, 2))
            offerings = [["A", p_a], ["B", p_b]]
        elif gid == "E2":
            offerings = [["C", max(74.0, round(c_price + 8.0, 2))], ["B", max(43.0, round(c_price + 4.0, 2))]]
        elif gid == "E3":
            offerings = [["C", max(58.0, round(c_price + 6.0, 2))], ["B", max(36.0, round(c_price + 4.0, 2))], ["A", 20.0]]
        else:
            offerings = [["B", max(25.0, round(c_price + 4.0, 2))], ["A", max(14.0, round(c_price, 2))]]
    deals.append([cid, offerings])

if deals:
    deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
    results = deal_res.get("results", [])
    ok_cnt = sum(1 for x in results if x.get("success"))
    print(f"send_enterprise_deal: {ok_cnt}/{len(results)} succeeded")
    if ok_cnt < len(results):
        print("Failures:", [x for x in results if not x.get("success")])

# 2. Lift retail prices alongside higher product quality & strong conversion
print("set_prices:", nm.pricing.set_prices(A=25.0, B=76.0, C=229.0))
print("set_model_tiers:", nm.pricing.set_model_tiers(A=2, B=3, C=4))
print("set_usage_quotas:", nm.pricing.set_usage_quotas(A=230, B=450, C=1100))

# 3. Keep Capacity Tier 4 (8M/d) and scale Operations to handle >13K subs + enterprise SLAs
print("set_capacity_tier:", nm.infrastructure.set_capacity_tier(tier=4))
print("set_daily_spend:", nm.marketing.set_daily_spend(operations=4500.0, development=2500.0))
print("set_targeted_ops_spend:", nm.analytics.set_targeted_ops_spend(by_group={
    "E1": 350.0,
    "E2": 250.0,
    "E3": 250.0,
    "D_E09": 75.0,
    "D_E02": 75.0,
}))

# 4. Disciplined Week 7 Dev Spend ($6,500/d targeted + $2,500/d global = $9,000/d) to ensure cash inflection
print("set_targeted_dev_spend:", nm.analytics.set_targeted_dev_spend(targeted_spend={
    "E2": 2500.0,
    "E3": 1500.0,
    "D_E02": 1000.0,
    "E1": 500.0,
    "S2": 500.0,
    "S3": 500.0,
}))

# 5. High-ROI Retail Ad Spend ($14,000/day)
ad_spend = {
    "content_marketing": {
        "S2": 6500.0,
        "S1": 1200.0,
    },
    "social_media": {
        "S2": 500.0,
    },
    "referral_program": {
        "S3": 4800.0,
        "S1": 1000.0,
    },
}
res_ad = nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)
print("set_targeted_ad_spend total_per_day:", res_ad.get("total_per_day"))

print("set_lead_promotion:", nm.marketing.set_lead_promotion(
    global_promotion=0.0,
    by_group={"S1": 1.0}
))

print("post_social_media:", nm.marketing.post_social_media(
    content="NovaMind now powers 13,000+ builders and enterprises with 99.99% uptime, zero-retention enterprise privacy, and automated document & code pipelines that cut cycle times in half."
))

