import json
import novamind_api as nm

print(f"Configuring Week 8 on day {nm.vars.current_day}...")

# 1. Reply to all open enterprise threads awaiting agent response
ent = nm.query("""
    SELECT t.message_id, t.thread_id, t.customer_id, c.group_id, t.thread_type,
           t.turn_number, t.sender, t.day, t.seat_count, t.offer_json, t.message_text
    FROM enterprise_turns t
    JOIN customers c ON t.customer_id = c.customer_id
    WHERE t.thread_id IN (
        SELECT thread_id FROM enterprise_turns GROUP BY thread_id HAVING MAX(COALESCE(closed, 0)) = 0
    )
    AND t.message_id IN (
        SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id
    )
    ORDER BY t.day, t.thread_id
""")

awaiting = [r for r in ent["rows"] if r["sender"] != "agent"]
print(f"Found {len(ent['rows'])} open threads, {len(awaiting)} awaiting agent reply.")

deals = []
for r in awaiting:
    cid = r["customer_id"]
    gid = r["group_id"]
    turn = r["turn_number"]
    if turn == 0:
        if gid == "E1":
            offerings = [["C", 25.0], ["B", 16.5], ["A", 11.0]]
        elif gid == "E2":
            offerings = [["C", 66.0], ["B", 41.0], ["A", 22.0]]
        elif gid == "E3":
            offerings = [["C", 74.0], ["B", 48.0], ["A", 26.0]]
        elif gid == "D_E02":
            offerings = [["C", 46.0], ["B", 28.0], ["A", 16.0]]
        elif gid == "D_E09":
            offerings = [["C", 40.0], ["B", 25.0], ["A", 14.5]]
        else:
            offerings = [["C", 60.0], ["B", 38.0], ["A", 20.0]]
    else:
        try:
            c_price = float(json.loads(r["offer_json"] or "{}").get("price", 10.0))
        except Exception:
            c_price = 10.0
        if gid == "E1":
            if c_price >= 11.0:
                offerings = [["B", round(max(11.5, c_price), 2)], ["A", 9.5]]
            elif c_price >= 8.0:
                offerings = [["B", round(max(11.5, c_price + 1.5), 2)], ["A", round(max(7.0, min(9.0, c_price)), 2)]]
            else:
                offerings = [["A", round(max(5.5, c_price), 2)], ["B", 12.0]]
        elif gid == "E2":
            if c_price >= 30.0:
                offerings = [["C", round(max(38.0, c_price + 5.0), 2)], ["B", 28.0], ["A", 17.0]]
            else:
                offerings = [["B", round(max(24.0, c_price + 6.0), 2)], ["A", 15.0]]
        elif gid == "E3":
            offerings = [["C", round(max(45.0, c_price + 5.0), 2)], ["B", round(max(28.0, c_price), 2)], ["A", 18.0]]
        elif gid == "D_E02":
            offerings = [["B", round(max(16.0, c_price + 3.0), 2)], ["A", round(max(10.5, c_price), 2)]]
        elif gid == "D_E09":
            offerings = [["B", round(max(16.0, c_price + 3.0), 2)], ["A", round(max(9.5, c_price), 2)]]
        else:
            offerings = [["B", round(max(20.0, c_price + 3.0), 2)], ["A", round(max(11.0, c_price), 2)]]
    deals.append([cid, offerings])

if deals:
    deal_res = nm.enterprise.send_enterprise_deal(deals=deals)
    results = deal_res.get("results", [])
    ok_cnt = sum(1 for x in results if x.get("success"))
    print(f"send_enterprise_deal: {ok_cnt}/{len(results)} succeeded")
    if ok_cnt < len(results):
        print("Failures:", [x for x in results if not x.get("success")][:5])

# 2. Lift retail prices alongside rising quality & >65% S2 conversion
print("set_prices:", nm.pricing.set_prices(A=26.0, B=82.0, C=239.0))
print("set_model_tiers:", nm.pricing.set_model_tiers(A=2, B=3, C=4))
print("set_usage_quotas:", nm.pricing.set_usage_quotas(A=230, B=450, C=1100))

# 3. Capacity Tier 4 (8M/d) + Scaled Global & Enterprise Operations
print("set_capacity_tier:", nm.infrastructure.set_capacity_tier(tier=4))
print("set_daily_spend:", nm.marketing.set_daily_spend(operations=6000.0, development=3000.0))
print("set_targeted_ops_spend:", nm.analytics.set_targeted_ops_spend(by_group={
    "E1": 500.0,
    "E2": 350.0,
    "E3": 350.0,
    "D_E02": 150.0,
    "D_E09": 150.0,
}))

# 4. Targeted Dev Spend ($9,500/d targeted + $3,000/d global = $12,500/d)
print("set_targeted_dev_spend:", nm.analytics.set_targeted_dev_spend(targeted_spend={
    "E2": 3000.0,
    "E3": 2000.0,
    "D_E02": 1500.0,
    "D_E09": 1000.0,
    "E1": 1000.0,
    "S2": 500.0,
    "S3": 500.0,
}))

# 5. High-ROI Retail Ad Spend ($15,000/d)
ad_spend = {
    "content_marketing": {
        "S2": 7500.0,
        "S1": 1200.0,
    },
    "social_media": {
        "S2": 500.0,
    },
    "referral_program": {
        "S3": 5200.0,
        "S1": 600.0,
    },
}
res_ad = nm.marketing.set_targeted_ad_spend(targeted_spend=ad_spend)
print("set_targeted_ad_spend total_per_day:", res_ad.get("total_per_day"))

print("set_lead_promotion:", nm.marketing.set_lead_promotion(
    global_promotion=0.0,
    by_group={"S1": 2.0}
))

print("post_social_media:", nm.marketing.post_social_media(
    content="Over 20,000 users and Fortune-500 enterprises now run production workflows on NovaMind—achieving 87% faster document & code synthesis with guaranteed sub-150ms P95 latency."
))

